Translate("esES", "ashenvale", {
	title = "Vallefresno",
	aliases = { "Bosque de Vallefresno" },
	sections = {
		{
			title = "Resumen",
			text = [=[Vallefresno es el gran bosque de los {link:night-elves}elfos de la noche{/link}, una tierra de árboles imponentes, lagos plateados y ruinas blancas en el norte de {link:kalimdor}Kalimdor{/link}. Se extiende desde el mar gris de {link:the-zoram-strand}La Ensanada de Zoram{/link}, al oeste, hasta el río que lo separa de {link:azshara}Azshara{/link}, al este. {link:darkshore}Costa Oscura{/link} y {link:felwood}Frondavil{/link} quedan al norte, y la {link:stonetalon-mountains}Sierra Espolón{/link} y {link:the-barrens}Los Baldíos{/link} al sur. Durante diez mil años, los elfos de la noche lo han conservado como un bosque sagrado. Ya no es sagrado solo para ellos. Las hachas de la {link:horde}Horda{/link} resuenan en sus valles orientales, y el bosque se ha convertido en el campo de batalla más antiguo y encarnizado entre los elfos y los orcos.]=],
		},
		{
			title = "Orígenes",
			text = [=[Los árboles de Vallefresno son más antiguos que cualquier crónica. Antes de la {link:great-sundering}Gran Fractura{/link}, ciudades de los elfos se alzaban a lo largo de su costa occidental, y la ciudad de {link:the-zoram-strand}Zoram{/link} se asomaba al mar. Cuando el {link:well-of-eternity}Pozo de la Eternidad{/link} fue destruido, el mar se alzó y se tragó Zoram, y las ruinas de los viejos templos quedaron dispersas por los bosques: {link:the-ruins-of-ordil-aran}Ordil'Aran{/link}, las {link:bathran-s-haunt}Ruinas de Bathran{/link}, las {link:the-ruins-of-stardust}Ruinas del Polvo Estelar{/link} y la ciudad de {link:xavian}Xavian{/link}, en el este. Tras la guerra, los elfos de la noche se asentaron a la sombra del {link:mount-hyjal}Monte Hyjal{/link} y se entregaron a las costumbres de {link:cenarius}Cenarius{/link} y de los druidas. Mientras los druidas dormían en el {link:emerald-dream}Sueño Esmeralda{/link}, las {link:sentinels}Centinelas{/link} de {link:tyrande-whisperwind}Tyrande Whisperwind{/link} vigilaron el bosque durante las eras de la Larga Vigilia. Ninguna crónica registra cuándo se levantaron por primera vez {link:astranaar}Astranaar{/link} o las demás aldeas del bosque.]=],
		},
		{
			title = "El presente",
			text = [=[Vallefresno no ha conocido la paz desde la {link:third-war}Tercera Guerra{/link}. Las {link:sentinels}Centinelas{/link} defienden {link:astranaar}Astranaar{/link}, la {link:maestra-s-post}Atalaya de Maestra{/link}, el {link:silverwind-refuge}Refugio Brisa de Plata{/link} y {link:forest-song}Canción del Bosque{/link}, pero sus filas son escasas y sus caminos, largos. Los fúrbolgs {link:thistlefur-village}Piel de Cardo{/link} y Foulweald, antaño amigos de los elfos, han sido envenenados por una corrupción que baja desde {link:felwood}Frondavil{/link}, y se abalanzan sobre todo viajero. Los sátiros dominan la {link:night-run}Senda de la Noche{/link}, {link:satyrnaar}Satyrnaar{/link} y {link:xavian}Xavian{/link}. Los {link:naga}nagas{/link} han vuelto a las ruinas anegadas de {link:the-zoram-strand}Zoram{/link}, y un culto del {link:twilight-s-hammer}Martillo Crepuscular{/link} se reúne en las salas inundadas de las {link:blackfathom-deeps}Cavernas de Brazanegra{/link}. En el este, los orcos Grito de Guerra talan madera para la {link:horde}Horda{/link} bajo la protección del {link:splintertree-post}Puesto del Hachazo{/link}. En la costa occidental han levantado una segunda avanzada, {link:zoram-gar-outpost}Zoram'gar{/link}. Los elfos responden a cada árbol talado con flechas, y cada estación la guerra entre ambos pueblos se adentra un poco más en los bosques.]=],
		},
		{
			title = "Habitantes",
			text = [=[• {b}Los elfos de la noche.{/b} {link:sentinels}Centinelas{/link}, druidas y sacerdotisas que defienden las aldeas del bosque y luchan por mantenerlo intacto.
• {b}Las dríades.{/b} Las hijas de {link:cenarius}Cenarius{/link} todavía danzan en los claros del {link:raynewood-retreat}Refugio de la Algaba{/link} y de {link:the-shrine-of-aessina}El Santuario de Aessina{/link}.
• {b}La {link:horde}Horda{/link}.{/b} Los orcos Grito de Guerra, con trols, {link:tauren}tauren{/link} y goblins a su lado, dominan el {link:splintertree-post}Puesto del Hachazo{/link}, los aserraderos del este y la {link:zoram-gar-outpost}Avanzada de Zoram'gar{/link} en la costa.
• {b}Los {link:forsaken}Renegados{/link}.{/b} Boticarios de {link:undercity}Entrañas{/link} se han infiltrado en los túmulos y ruinas de los elfos.
• {b}Los fúrbolgs.{/b} Los {link:thistlefur-village}Piel de Cardo{/link} del norte y los Foulweald del sur, enloquecidos, y los {link:bloodtooth-camp}Sangradientes{/link}, que siguen a un rey salvaje.
• {b}Los sátiros.{/b} Los sátiros Felmusk, Bleakheart y {link:xavian}Xavian{/link} adoran a demonios en los templos en ruinas del este.
• {b}Los nagas.{/b} Los nagas Wrathtail rondan {link:the-zoram-strand}La Ensanada de Zoram{/link} y las aguas de {link:blackfathom-deeps}Brazanegra{/link}.
• {b}Los demonios.{/b} Guardias viles e infernales aún acechan en el barranco donde cayó {link:mannoroth}Mannoroth{/link}.]=],
		},
		{
			title = "Historia",
			text = [=[• {b}La ciudad anegada.{/b} En la {link:great-sundering}Fractura{/link}, el mar se llevó {link:the-zoram-strand}Zoram{/link}. Sus gobernantes, su anillo y sus secretos se hundieron con ella.
• {b}La Larga Vigilia.{/b} Durante diez mil años las {link:sentinels}Centinelas{/link} guardaron Vallefresno mientras los druidas dormían, y el bosque creció profundo y silencioso.
• {b}La llegada de los orcos.{/b} En la {link:third-war}Tercera Guerra{/link}, los orcos de {link:grom-hellscream}Grom Hellscream{/link} llegaron a Vallefresno a talar madera para su nuevo hogar. Las Centinelas contraatacaron, y el propio {link:cenarius}Cenarius{/link} se alzó para defender el bosque. Grom y sus guerreros bebieron de un manantial corrompido por la sangre de {link:mannoroth}Mannoroth{/link}, y en aquella furia mataron al semidiós. Después, en un barranco del bosque oriental, Grom mató a Mannoroth y liberó a su pueblo de la maldición de sangre, pero murió de sus heridas.
• {b}Hyjal.{/b} En la {link:battle-of-mount-hyjal}Batalla del Monte Hyjal{/link}, elfos, orcos y humanos se unieron contra {link:archimonde}Archimonde{/link}, y la Legión fue derrotada. La alianza de aquel día no sobrevivió a la victoria.
• {b}El presente.{/b} La {link:horde}Horda{/link} sigue talando los árboles de Vallefresno. Los elfos de la noche nunca lo han aceptado.]=],
		},
		{
			title = "Saber del bosque",
			text = [=[• Se dice que el Tomo de {link:the-howling-vale}Mel'Thandris{/link}, guardado en un santuario en ruinas cerca de la frontera de {link:felwood}Frondavil{/link}, registra por sí solo en sus hojas los acontecimientos importantes. Nadie entiende cómo.
• Un {link:furbolgs}fúrbolg{/link} llamado {link:krolg}Krolg{/link} vive solo junto al {link:mystral-lake}Lago Mystral{/link}. Solo habla con los de su especie, y culpa a los elfos de la ruina de su pueblo.
• Los cazadores del {link:splintertree-post}Hachazo{/link} hablan de tres grandes bestias del bosque: el oso {link:ursangous}Ursangous{/link}, la sable de la noche {link:shadumbra}Shadumbra{/link} y el hipogrifo {link:sharptalon}Sharptalon{/link}. Abatir a las tres es una prueba de la valía de cualquier cazador.
• Los sátiros han robado la Rama de {link:cenarius}Cenarius{/link} a las dríades, y las dríades no lo han perdonado.]=],
		},
	},
})

Translate("esES", "astranaar", {
	title = "Astranaar",
	sections = {
		{
			title = "Resumen",
			text = [=[Astranaar es el pueblo principal de los elfos de la noche en {link:ashenvale}Vallefresno{/link}. Se alza en una isla de un lago en el corazón del bosque, unida a la orilla por puentes de piedra blanca. Aquí {link:raene-wolfrunner}Raene Wolfrunner{/link} manda a las {link:sentinels}Centinelas{/link} de la región, y desde aquí parten exploradores hacia todos los rincones del bosque. El pueblo tiene una posada, un nido de hipogrifos y un pequeño mercado de artesanos elfos. También se ha convertido en una casa de preocupaciones. Sus centinelas informan de que los fúrbolgs aumentan en número al norte, una niña yace enferma en uno de sus hogares y la guerra con la {link:horde}Horda{/link} se acerca a sus puentes cada estación.]=],
		},
	},
})

Translate("esES", "maestra-s-post", {
	title = "Atalaya de Maestra",
	aliases = { "Maestra" },
	sections = {
		{
			title = "Resumen",
			text = [=[La Atalaya de Maestra es una pequeña avanzada élfica en el noroeste de {link:ashenvale}Vallefresno{/link}, en el camino que baja desde {link:darkshore}Costa Oscura{/link}. Es el primer refugio que encuentra en el bosque un viajero que viene de {link:auberdine}Auberdine{/link}. Las {link:sentinels}Centinelas{/link} montan guardia en ella, y el druida {link:orendil-broadleaf}Orendil Broadleaf{/link} prepara allí sus remedios. Un paladín humano, {link:delgren-the-purifier}Delgren el Purificador{/link}, ha hecho de ella su base en su guerra contra el {link:cult-of-the-dark-strand}Culto de la Hebra Oscura{/link}, y sus mensajeros llevan suministros al norte, a Auberdine. Los druidas recién despertados del {link:emerald-dream}Sueño Esmeralda{/link} son enviados aquí para que los reciban.]=],
		},
	},
})

Translate("esES", "bathran-s-haunt", {
	title = "Ruinas de Bathran",
	sections = {
		{
			title = "Resumen",
			text = [=[Las Ruinas de Bathran son una ruina de los elfos en las colinas del norte de {link:ashenvale}Vallefresno{/link}, justo al sur de la frontera de {link:darkshore}Costa Oscura{/link}. Entre sus piedras crecía antes una planta llamada pelo de Bathran, y los druidas la apreciaban como cura para las enfermedades del espíritu. La ruina ya no está vacía. Los {link:forsaken}Renegados{/link} han acampado entre sus muros, y sus herboristas recogen lo que allí crece para fines propios. A los druidas de la {link:maestra-s-post}Atalaya de Maestra{/link} su presencia les inquieta mucho.]=],
		},
	},
})

Translate("esES", "the-ruins-of-ordil-aran", {
	title = "Las Ruinas de Ordil'Aran",
	aliases = { "Ordil'Aran" },
	sections = {
		{
			title = "Resumen",
			text = [=[Ordil'Aran es un pueblo derruido de los antiguos elfos en el norte de {link:ashenvale}Vallefresno{/link}, al noreste de la {link:maestra-s-post}Atalaya de Maestra{/link}. Su nombre recuerda a los pueblos gemelos de {link:ameth-aran}Ameth'Aran{/link} y {link:bashal-aran}Bashal'Aran{/link}, en {link:darkshore}Costa Oscura{/link}, que se construyeron para los Altonato en los días de la {link:queen-azshara}reina Azshara{/link}. Ahora los brujos del {link:cult-of-the-dark-strand}Culto de la Hebra Oscura{/link} excavan entre sus piedras. Uno de ellos llevaba una gema de alma que guardaba el secreto del poder del culto, hasta que {link:delgren-the-purifier}Delgren el Purificador{/link} envió a un campeón a arrebatársela.]=],
		},
	},
})

Translate("esES", "the-zoram-strand", {
	title = "La Ensanada de Zoram",
	aliases = { "Ensanada de Zoram", "Zoram" },
	sections = {
		{
			title = "Resumen",
			text = [=[La Ensanada de Zoram es la costa occidental de {link:ashenvale}Vallefresno{/link}, una orilla de arena gris y columnas rotas. Bajo las olas yace Zoram, una ciudad de los elfos que el mar se tragó en la {link:great-sundering}Gran Fractura{/link}. Durante eras estuvo casi olvidada. Ahora los {link:naga}nagas{/link} han regresado a ella, y nadie sabe qué buscan. Los nagas Wrathtail, con hidras a su lado, dominan la orilla y sus islas. En el extremo norte de la ensenada, un gran templo medio hundido en el mar se abre a las profundidades de las {link:blackfathom-deeps}Cavernas de Brazanegra{/link}.]=],
		},
	},
})

Translate("esES", "zoram-gar-outpost", {
	title = "Avanzada de Zoram'gar",
	aliases = { "Zoram'gar" },
	sections = {
		{
			title = "Resumen",
			text = [=[Zoram'gar es la avanzada de la {link:horde}Horda{/link} en {link:the-zoram-strand}La Ensanada de Zoram{/link}, un campamento de orcos y trols en una lengua de tierra junto al mar. Se construyó para reclamar para la Horda la costa occidental de {link:ashenvale}Vallefresno{/link}, y para vigilar a los nagas y las ruinas de {link:blackfathom-deeps}Brazanegra{/link}. {link:karang-amakkar}Karang Amakkar{/link} la manda. El trol {link:je-neu-sancrea}Je'neu Sancrea{/link}, del {link:earthen-ring}Anillo de la Tierra{/link}, estudia el mar desde su orilla. El campamento está en apuros. Los nagas lo asaltan, una gran hidra lo ha atacado más de una vez y los fúrbolgs {link:thistlefur-village}Piel de Cardo{/link} se interponen entre él y el {link:splintertree-post}Puesto del Hachazo{/link}.]=],
		},
	},
})

Translate("esES", "lake-falathim", {
	title = "Lago Falathim",
	sections = {
		{
			title = "Resumen",
			text = [=[El Lago Falathim se encuentra al pie de las montañas del oeste de {link:ashenvale}Vallefresno{/link}. En su isla se alzaba un santuario donde los elfos guardaban una gema luminosa, hasta que el santuario fue invadido. Los {link:murlocs}múrlocs{/link} de la tribu Saltspittle dominan ahora la orilla. Fue aquí donde el elfo {link:teronis}Teronis{/link} vino en busca de la gema, y aquí donde sus amigos encontraron su cuerpo, desgarrado por garras de múrloc, intacto sobre la isla.]=],
		},
	},
})

Translate("esES", "the-shrine-of-aessina", {
	title = "El Santuario de Aessina",
	aliases = { "Santuario de Aessina", "Aessina" },
	sections = {
		{
			title = "Resumen",
			text = [=[El Santuario de Aessina es un claro oculto en las montañas del oeste de {link:ashenvale}Vallefresno{/link}, rodeado de acantilados y al que llegan pocos senderos. En él se alza un santuario de un poder grande y sutil, donde se concentra la magia del bosque. Allí viven dríades, entre ellas {link:therysil}Therysil{/link} e {link:illiyana}Illiyana{/link}, y la centinela {link:sentinel-melyria-frostshadow}Melyria Frostshadow{/link} vigila {link:moonglade}el claro{/link}. Quienes buscan renovar un encantamiento vienen a depositar su obra en su pila, y esperan a que brille.]=],
		},
	},
})

Translate("esES", "fire-scar-shrine", {
	title = "Santuario de la Escara",
	aliases = { "Escara" },
	sections = {
		{
			title = "Resumen",
			text = [=[El Santuario de la Escara es un lugar de gran maldad en el suroeste de {link:ashenvale}Vallefresno{/link}. Su suelo está quemado y sus árboles, muertos. Aquí tiene su guarida el brujo {link:orcs}orco{/link} {link:ilkrud-magthrull}Ilkrud Magthrull{/link}, y los demonios acuden a su llamada. Un demonio llamado Akkrilus camina entre las cenizas. Los elfos consideraron una vez a Ilkrud una simple molestia. Eso cambió cuando {link:delgren-the-purifier}Delgren el Purificador{/link} descubrió que el brujo guardaba notas sobre los planes del {link:cult-of-the-dark-strand}Culto de la Hebra Oscura{/link}.]=],
		},
	},
})

Translate("esES", "thistlefur-village", {
	title = "Poblado Piel de Cardo",
	aliases = { "Guarida Piel de Cardo", "Piel de Cardo" },
	sections = {
		{
			title = "Resumen",
			text = [=[El Poblado Piel de Cardo es el hogar de los {link:furbolgs}fúrbolgs{/link} Piel de Cardo, al norte de {link:astranaar}Astranaar{/link}. Sus chozas se extienden por el bosque, y al final del poblado una cueva, la guarida Piel de Cardo, se adentra en la colina. Los Piel de Cardo no siempre fueron enemigos, pero ahora están corrompidos, y su número ha crecido mucho en los últimos meses. Las {link:sentinels}Centinelas{/link} temen que lleguen a atreverse a atacar la propia Astranaar. La {link:horde}Horda{/link} también los teme, porque el poblado bloquea el camino entre {link:zoram-gar-outpost}Zoram'gar{/link} y el {link:splintertree-post}Hachazo{/link}.]=],
		},
	},
})

Translate("esES", "iris-lake", {
	title = "Lago Iris",
	sections = {
		{
			title = "Resumen",
			text = [=[El Lago Iris se encuentra al este de {link:astranaar}Astranaar{/link}, un agua tranquila con un islote en su centro. En ese islote descansa una piedra llamada Lágrima de Elune, que no se encuentra en ningún otro lugar del mundo. Los druidas dicen que puede lavar la corrupción. Cuando la hija de {link:pelturas-whitemoon}Pelturas Whitemoon{/link} yacía enferma de pesadillas, fue la Lágrima del Lago Iris la que las alivió.]=],
		},
	},
})

Translate("esES", "the-ruins-of-stardust", {
	title = "Las Ruinas del Polvo Estelar",
	aliases = { "Ruinas del Polvo Estelar" },
	sections = {
		{
			title = "Resumen",
			text = [=[Las Ruinas del Polvo Estelar se encuentran al sur de {link:astranaar}Astranaar{/link}, entre los árboles del bosque meridional. Poco queda en pie allí salvo piedra rota. Sin embargo, entre las ruinas se acumula un polvo escarchado, y los druidas saben que puede calmar la fiebre. El nombre del lugar es más antiguo que cualquier registro, y los elfos solo dicen que se llamó así por el polvo.]=],
		},
	},
})

Translate("esES", "mystral-lake", {
	title = "Lago Mystral",
	sections = {
		{
			title = "Resumen",
			text = [=[El Lago Mystral es una amplia extensión de agua en el sur de {link:ashenvale}Vallefresno{/link}, cerca de la entrada de {link:the-talondeep-path}El Paso del Espolón{/link}, que conduce a la {link:stonetalon-mountains}Sierra Espolón{/link}. Sus aguas han cobrado vida. De ellas surgen elementales corrompidos que atacan todo lo que se acerca, y el camino entre el bosque y el Espolón está casi cerrado. Un cenador en {link:the-loch}el lago{/link} domina el refugio élfico de su orilla, y tanto las {link:sentinels}Centinelas{/link} como la {link:horde}Horda{/link} se interesan por quién vigila desde él. En la orilla sur vive {link:krolg}Krolg{/link}, un {link:furbolgs}fúrbolg{/link} que ha escapado de la corrupción de los suyos.]=],
		},
	},
})

Translate("esES", "silverwind-refuge", {
	title = "Refugio Brisa de Plata",
	aliases = { "Brisa de Plata" },
	sections = {
		{
			title = "Resumen",
			text = [=[El Refugio Brisa de Plata es una aldea de los elfos de la noche en la orilla sur del {link:mystral-lake}Lago Mystral{/link}. Tiene sus propios comerciantes, instructores y alquimistas, y un nido de hipogrifos. La centinela {link:sentinel-velene-starstrike}Velene Starstrike{/link} manda su guardia. Últimamente el refugio no ha tenido descanso, porque {link:the-loch}el lago{/link} que tiene al lado se llena de elementales inmundos. Velene ha descubierto quién los crea, y ha jurado que lo pagará.]=],
		},
	},
})

Translate("esES", "fallen-sky-lake", {
	title = "Lago Cielo Estrellado",
	sections = {
		{
			title = "Resumen",
			text = [=[El Lago Cielo Estrellado se encuentra en el sureste de {link:ashenvale}Vallefresno{/link}. Los elfos recogían antes en su orilla piedras lunares, piedras que cayeron del cielo y portan la fuerza de la luna. Entonces llegaron los Shadethicket. Son antárboles retorcidos, y su oráculo ha reunido todas las piedras lunares caídas en su propio tesoro. Los elfos ya no van al lago.]=],
		},
	},
})

Translate("esES", "raynewood-retreat", {
	title = "Refugio de la Algaba",
	aliases = { "la Algaba" },
	sections = {
		{
			title = "Resumen",
			text = [=[El Refugio de la Algaba es una arboleda elevada en el corazón de {link:ashenvale}Vallefresno{/link}, coronada por un gran árbol del mismo nombre. Unas dríades llamadas las Hermanas Risueñas juegan en sus claros, y guerreros cenarion guardan sus senderos. En lo alto del árbol vive el guardián {link:keeper-ordanus}Ordanus{/link}, un hijo de {link:cenarius}Cenarius{/link}, al que trajeron aquí en secreto desde las cumbres del {link:stonetalon-mountains}Espolón{/link} cuando un brujo del {link:shadow-council}Consejo de la Sombra{/link} buscó su vida. Ciervos y grandes osos vagan por las laderas de abajo, y la sable de la noche {link:shadumbra}Shadumbra{/link} caza entre ellos.]=],
		},
	},
})

Translate("esES", "the-howling-vale", {
	title = "Vega del Aullido",
	aliases = { "Vega del Aullido", "Mel'Thandris" },
	sections = {
		{
			title = "Resumen",
			text = [=[La Vega del Aullido se encuentra en el norte de {link:ashenvale}Vallefresno{/link}, cerca de la frontera de {link:felwood}Frondavil{/link}. Su corazón es el santuario en ruinas de Mel'Thandris, donde se guarda un extraño tomo. La propia Mel'Thandris bendijo sus páginas, y por un poder que nadie sabe explicar, estas recogen los grandes acontecimientos de la tierra. Últimamente, hombres lobo se han apoderado del santuario. Sus escalofriantes aullidos dieron nombre a la vega. El tomo mostró a las {link:sentinels}Centinelas{/link} que esas criaturas están ligadas a una sacerdotisa que desapareció, y a una reliquia llamada la {red:scythe-of-elune}Guadaña de Elune{/red}.]=],
		},
	},
})

Translate("esES", "night-run", {
	title = "Senda de la Noche",
	sections = {
		{
			title = "Resumen",
			text = [=[La Senda de la Noche es un valle en poder de los sátiros en el noreste de {link:ashenvale}Vallefresno{/link}. Sus templos están empapados de sangre, e incluso los guerreros curtidos los encuentran inquietantes. Aquí el señor Altonato {link:athrikus-narassin}Athrikus Narassin{/link} escondió una de sus últimas gemas de alma, y el alma atrapada de un Altonato esperó en ella hasta que fue liberada. Los sátiros de la Senda de la Noche también guardan aceite robado a los Grito de Guerra, que queman en sus rituales.]=],
		},
	},
})

Translate("esES", "satyrnaar", {
	title = "Satyrnaar",
	sections = {
		{
			title = "Resumen",
			text = [=[Satyrnaar es el bastión de los sátiros Felmusk en el este de {link:ashenvale}Vallefresno{/link}, una ruina envuelta en sombra vil. Es uno de los lugares donde {link:athrikus-narassin}Athrikus Narassin{/link} guardaba una gema de alma, y donde un alma Altonato yacía prisionera. Como la {link:night-run}Senda de la Noche{/link} y {link:xavian}Xavian{/link}, fue un templo en otro tiempo. El paladín {link:delgren-the-purifier}Delgren el Purificador{/link} ha oído decir que la historia de los sátiros está ligada a la de los elfos de la noche, pero sus anfitriones no quieren hablar de ello.]=],
		},
	},
})

Translate("esES", "xavian", {
	title = "Xavian",
	sections = {
		{
			title = "Resumen",
			text = [=[Xavian es una legendaria ciudad de los antiguos elfos, enclavada en las colinas del este de {link:ashenvale}Vallefresno{/link}. Los eruditos hablan de su saber perdido, y se dice que las aguas de su cascada más alta encierran una gran magia. Los sátiros Xavian gobiernan ahora sus ruinas, con pícaros, jurados viles e invocadores infernales entre ellos. Su amo, {link:geltharis}Geltharis{/link}, robó la Rama de {link:cenarius}Cenarius{/link} a las dríades. Tres hermanas dríades entraron en Xavian para recuperarla. Solo una salió con vida, y no por mucho tiempo.]=],
		},
	},
})

Translate("esES", "forest-song", {
	title = "Canción del Bosque",
	aliases = { "Bosque Arrullanoche" },
	sections = {
		{
			title = "Resumen",
			text = [=[Canción del Bosque es un santuario de los elfos de la noche en el Bosque Arrullanoche, en el este de {link:ashenvale}Vallefresno{/link}, cerca de la frontera de {link:azshara}Azshara{/link}. El druida {link:kayneth-stillwind}Kayneth Stillwind{/link} lo custodia. Desde aquí lee los informes de las {link:sentinels}Centinelas{/link} y busca en ellos señales de una maldad que teme que se mueve por el bosque. El santuario está cerca de los aserraderos de la {link:horde}Horda{/link} y de las ruinas sátiras de {link:xavian}Xavian{/link}, y sus druidas rara vez duermen tranquilos.]=],
		},
	},
})

Translate("esES", "bough-shadow", {
	title = "Talloumbrío",
	sections = {
		{
			title = "Resumen",
			text = [=[Talloumbrío es un gran árbol en el extremo noreste de {link:ashenvale}Vallefresno{/link}, más allá de {link:forest-song}Canción del Bosque{/link}. Es uno de los cuatro árboles que, según los druidas, son puertas al {link:emerald-dream}Sueño Esmeralda{/link}. Dracónidos verdes montan guardia bajo él, y grandes dracos verdes sobrevuelan su copa. No permiten que nadie se acerque, y los elfos de Canción del Bosque los dejan en paz.]=],
		},
	},
})

Translate("esES", "splintertree-post", {
	title = "Puesto del Hachazo",
	aliases = { "Hachazo" },
	sections = {
		{
			title = "Resumen",
			text = [=[El Puesto del Hachazo es el bastión de la {link:horde}Horda{/link} en el este de {link:ashenvale}Vallefresno{/link}, un campamento amurallado de chozas orcas sobre una colina que domina el camino a {link:the-barrens}Los Baldíos{/link}. Protege los aserraderos Grito de Guerra y los caminos que llevan su madera hacia el sur. Sus guerreros, cazadores y comerciantes proceden de todos los pueblos de la Horda. {link:mastok-wrilehiss}Mastok Wrilehiss{/link} refunfuña a su puerta, {link:senani-thunderheart}Senani Thunderheart{/link} pone a prueba a los jóvenes cazadores y {link:ertog-ragetusk}Ertog Ragetusk{/link} planea los asaltos contra los elfos. Pocas noches pasan allí sin una alarma.]=],
		},
	},
})

Translate("esES", "warsong-lumber-camp", {
	title = "Aserradero Grito de Guerra",
	aliases = { "Campo de trabajos forzados Grito de Guerra" },
	sections = {
		{
			title = "Resumen",
			text = [=[El Aserradero Grito de Guerra se encuentra en el extremo este de {link:ashenvale}Vallefresno{/link}, cerca del río que separa el bosque de {link:azshara}Azshara{/link}. Aquí los peones del clan Grito de Guerra talan los grandes árboles de los elfos y envían la madera al sur para construir y alimentar a la {link:horde}Horda{/link}. Las trituradoras goblin rugen entre los tocones, y los gruñones protegen a los trabajadores de las flechas de las {link:sentinels}Centinelas{/link}. Esta es la labor que trajo a {link:grom-hellscream}Grom Hellscream{/link} a Vallefresno en la {link:third-war}Tercera Guerra{/link}, y nunca se ha detenido. El campamento vive de suministros: hojas de sierra de {link:ratchet}Trinquete{/link}, hachas de {link:booty-bay}Bahía del Botín{/link}, aceite y cuerda que los sátiros y los fúrbolgs no dejan de robar.]=],
		},
	},
})

Translate("esES", "demon-fall-canyon", {
	title = "Barranco del Demonio",
	aliases = { "Cresta del Demonio", "Caída del Demonio", "Cerro Lumbrevil" },
	sections = {
		{
			title = "Resumen",
			text = [=[El Barranco del Demonio es una profunda garganta en el sureste de {link:ashenvale}Vallefresno{/link}, y su nombre recuerda la hazaña más famosa de la {link:third-war}Tercera Guerra{/link}. En un barranco de este bosque, {link:grom-hellscream}Grom Hellscream{/link} clavó su hacha en el señor del foso {link:mannoroth}Mannoroth{/link} y liberó a los orcos de la sangre del demonio, y allí murió. El barranco no ha sido purificado. Guardias viles montan guardia en él, infernales humean entre sus rocas y canes de la Legión cazan en la cresta de arriba. En el Cerro Lumbrevil, al sur, un señor del terror llamado Diathorus el Buscador los manda.]=],
		},
	},
})

Translate("esES", "the-dor-danil-barrow-den", {
	title = "El Túmulo de Dor'danil",
	aliases = { "Túmulo de Dor'danil", "Dor'Danil" },
	sections = {
		{
			title = "Resumen",
			text = [=[El Túmulo de Dor'danil se encuentra en el sureste de {link:ashenvale}Vallefresno{/link}, al este del camino a {link:the-barrens}Los Baldíos{/link}. Sus druidas dormían aquí antes y custodiaban un fragmento de una vieja vara. Entonces llegaron los {link:forsaken}Renegados{/link}. Levantaron un campamento junto a los túmulos, prepararon sus enfermedades y envenenaron a los druidas mientras dormían. Los espíritus de los druidas de Dor'Danil se alzaron separados de sus cuerpos y enloquecidos, y ahora vagan por los túmulos junto a los no-muertos que los mataron.]=],
		},
	},
})

Translate("esES", "silverwing-outpost", {
	title = "Avanzada Ala de Plata",
	aliases = { "Claro Ala de Plata" },
	sections = {
		{
			title = "Resumen",
			text = [=[La Avanzada Ala de Plata es un campamento de las {link:sentinels}Centinelas{/link} en el sur de {link:ashenvale}Vallefresno{/link}, situado entre los árboles al oeste de los caminos madereros de la {link:horde}Horda{/link}. Sus batidoras se deslizan por el bosque para espiar a los orcos, y sus guerreras están listas para golpear el {link:splintertree-post}Hachazo{/link}. {link:duriel-moonfire}Duriel Moonfire{/link} la dirige. La Horda la considera una daga clavada en su costado, y sus asaltantes han jurado tomarla.]=],
		},
	},
})

Translate("esES", "bloodtooth-camp", {
	title = "Asentamiento Sangradientes",
	aliases = { "Sangradientes" },
	sections = {
		{
			title = "Resumen",
			text = [=[El Asentamiento Sangradientes es la guarida del {link:furbolgs}fúrbolg{/link} {link:ran-bloodtooth}Ran Bloodtooth{/link} y de sus guardias, en el sur de {link:ashenvale}Vallefresno{/link}, cerca del límite de {link:the-barrens}Los Baldíos{/link}. Ran es el más feroz de los fúrbolgs corrompidos, un rey entre los suyos, y la corrupción no ha hecho más que fortalecerlo. Incluso otros fúrbolgs temen lo que sale de este asentamiento.]=],
		},
	},
})

Translate("esES", "greenpaw-village", {
	title = "Poblado Zarpaverde",
	aliases = { "Túmulo tótem Foulweald" },
	sections = {
		{
			title = "Resumen",
			text = [=[El Poblado Zarpaverde es el hogar de los fúrbolgs Foulweald, al sur del camino que sale de {link:astranaar}Astranaar{/link} hacia el este y al oeste del Río Falfarren. En su corazón se alza el túmulo tótem de la tribu. Los Foulweald son menos numerosos que los {link:thistlefur-village}Piel de Cardo{/link}, pero más feroces, y atacan a los viajeros en el camino. Tanto las {link:sentinels}Centinelas{/link} como la {link:horde}Horda{/link} los han golpeado. Cuando se alzó un estandarte de la Horda sobre su túmulo, su jefe salió a defender el honor de su tribu, y cayó.]=],
		},
	},
})

Translate("esES", "raene-wolfrunner", {
	title = "Raene Wolfrunner",
	subtitle = "Comandante de las Centinelas de Astranaar",
	found = "Astranaar, junto a sus dos bestias",
	hint = [=[Hable con la cazadora que manda a las Centinelas de Astranaar.]=],
	allegiance = "Centinelas · Darnassus",
	aliases = { "Raene" },
	sections = {
		{
			title = "Resumen",
			text = [=[Raene Wolfrunner dirige a las {link:sentinels}Centinelas{/link} de {link:astranaar}Astranaar{/link}. Es una cazadora que tiene a su lado un lobo y un gran felino, y todos los informes del bosque pasan por sus manos. Pide ayuda hasta en {link:darkshore}Costa Oscura{/link}, y quienes responden la encuentran serena, grave y muy falta de guerreros.]=],
		},
		{
			title = "Importancia",
			text = [=[Raene defiende el corazón de {link:ashenvale}Vallefresno{/link} para los elfos de la noche en un momento en que sus enemigos presionan por todas partes. Su guerra se libra en dos frentes a la vez: contra la {link:horde}Horda{/link} y contra la corrupción que ha convertido a los fúrbolgs del bosque en bestias.]=],
		},
		{
			title = "Hazañas",
			text = [=[• Envía exploradores y voluntarios contra los {link:thistlefur-village}Piel de Cardo{/link} y los Foulweald.
• Retomó la labor de su amigo {link:teronis}Teronis{/link} tras su muerte.
• Guarda en un lugar de honor de {link:astranaar}Astranaar{/link} el cráneo de un rey {link:furbolgs}fúrbolg{/link} y una vieja vara.]=],
		},
	},
	chapters = {
		{
			title = "La muerte de Teronis",
			hint = [=[Busque noticias del amigo perdido de Raene en una isla al oeste.]=],
			text = [=[El amigo de Raene, {link:teronis}Teronis{/link}, fue al oeste, al {link:lake-falathim}Lago Falathim{/link}, en busca de una gema, y no regresó. Había estado buscando las piezas de una vara hecha por un hechicero muerto, Dartol, que según él podía frenar los ataques de los fúrbolgs. Su cuerpo apareció en la isla, desgarrado por garras de {link:murlocs}múrloc{/link}. Raene dejó a un lado su dolor. El momento del luto llegaría después. Lo que importaba ahora era que su trabajo no se perdiera.]=],
		},
		{
			title = "La vara de Dartol",
			hint = [=[Reúna las piezas de la vara y busque a la dríade de la poza de la luna.]=],
			text = [=[A partir de las notas del diario de {link:teronis}Teronis{/link}, se siguió el rastro de las piezas de la vara de Dartol por todo el bosque: una custodiada por antárboles corrompidos cerca de {link:felwood}Frondavil{/link}, otra escondida con los druidas condenados de {link:the-dor-danil-barrow-den}Dor'Danil{/link}. La dríade {link:shael-dryn}Shael'dryn{/link} las unió, y un santuario oculto devolvió a la vara su poder. Podía dar a su portador la forma de un {link:furbolgs}fúrbolg{/link}. Raene no sabía qué había pretendido hacer Teronis con ella. Suponía que esperaba hablar con un fúrbolg aún intacto por el musgo vil.]=],
		},
		{
			title = "El cráneo de Ran Bloodtooth",
			hint = "Averigüe qué pide a los suyos el fúrbolg incorrupto.",
			text = [=[La vara condujo hasta {link:krolg}Krolg{/link}, un {link:furbolgs}fúrbolg{/link} que había escapado de la corrupción y que culpaba a los elfos de todo lo que había caído sobre su pueblo. Aun así, Krolg no quería ver sufrir por ello a niños elfos. Pidió que los fúrbolgs pusieran orden entre los suyos, y así murió {link:ran-bloodtooth}Ran Bloodtooth{/link}, el más feroz de los fúrbolgs corrompidos. Raene colocó su cráneo y la vara de Dartol donde toda {link:astranaar}Astranaar{/link} pudiera verlos, y dijo que {link:teronis}Teronis{/link} estaría orgulloso.]=],
		},
	},
	mentions = {
		{ text = "Viaje a {link:ashenvale}Vallefresno{/link}" },
		{ text = "Una defensa agresiva" },
		{ text = "Reducir la amenaza" },
		{ text = "La purificación de Raene" },
	},
	bonds = {
		{ id = "teronis", name = "Teronis", note = "su amigo, cuya labor completó" },
		{ id = "shael-dryn", name = "Shael'dryn", note = "ayudó a rehacer la vara de Dartol" },
		{ id = "krolg", name = "Krolg", note = "el fúrbolg que ayudó a su causa" },
		{ id = "ran-bloodtooth", name = "Ran Bloodtooth", note = "enemigo" },
		{ id = "dal-bloodclaw", name = "Dal Bloodclaw", note = "enemigo" },
		{ id = "sentinel-thenysil", name = "Centinela Thenysil", note = "una centinela a sus órdenes" },
	},
})

Translate("esES", "teronis", {
	title = "Teronis",
	subtitle = "Buscador de la vara de Dartol",
	found = "La isla del Lago Falathim",
	hint = [=[Busque al amigo perdido de las Centinelas en una isla del oeste.]=],
	allegiance = "Centinelas",
	sections = {
		{
			title = "Resumen",
			text = [=[Teronis era un amigo de {link:raene-wolfrunner}Raene Wolfrunner{/link} que ayudaba a las {link:sentinels}Centinelas{/link} de {link:ashenvale}Vallefresno{/link}. Creía que una vara hecha hace mucho por el hechicero Dartol podía frenar los ataques de los fúrbolgs contra los elfos. Fue al {link:lake-falathim}Lago Falathim{/link} a buscar una gema para ella, en un santuario que los múrlocs habían invadido. Nunca volvió. Su cuerpo apareció en la isla, desgarrado por hojas y garras de {link:murlocs}múrloc{/link}. Por razones que nadie entiende, los múrlocs no lo habían tocado.]=],
		},
		{
			title = "Hazañas",
			text = [=[• Siguió el rastro de las piezas de la vara de Dartol y llevó un diario de su búsqueda.
• Su diario llevó a otros a terminar lo que él empezó.]=],
		},
	},
	mentions = {
		{ text = "La purificación de {link:raene-wolfrunner}Raene{/link}" },
		{ text = "La purificación de {link:raene-wolfrunner}Raene{/link}" },
	},
	bonds = {
		{ id = "raene-wolfrunner", name = "Raene Wolfrunner", note = "su amiga" },
	},
})

Translate("esES", "shael-dryn", {
	title = "Shael'dryn",
	subtitle = "Dríade de la poza de la luna",
	found = [=[Una poza de la luna al norte del camino oriental, al este del Lago Iris]=],
	hint = [=[Busque a la dríade que cuida una poza de la luna al norte del camino, al este del Lago Iris.]=],
	allegiance = "Elfos de la noche · Cenarius",
	sections = {
		{
			title = "Resumen",
			text = [=[Shael'dryn es una dríade que cuida una poza de la luna en el corazón de {link:ashenvale}Vallefresno{/link}. Conoció en su día la creación de Dartol y a los antárboles que la custodiaban, pero los antárboles han sido corrompidos, y le apena no poder ayudarlos. Cuando le llevaron el trabajo de {link:teronis}Teronis{/link}, dijo dónde estaban escondidas las piezas de la vara, reconstruyó la vara con sus propias manos y envió a su portador a un santuario oculto para despertarla. Se ríe con facilidad, incluso en estos tiempos.]=],
		},
		{
			title = "Hazañas",
			text = [=[• Reconstruyó la vara de Dartol a partir de sus tres piezas.
• Guió la búsqueda de la llave que guardaban los antárboles corrompidos.]=],
		},
	},
	mentions = {
		{ text = "La purificación de {link:raene-wolfrunner}Raene{/link}" },
		{ text = "La purificación de {link:raene-wolfrunner}Raene{/link}" },
		{ text = "La purificación de {link:raene-wolfrunner}Raene{/link}" },
		{ text = "La purificación de {link:raene-wolfrunner}Raene{/link}" },
		{ text = "La purificación de {link:raene-wolfrunner}Raene{/link}" },
	},
	bonds = {
		{ id = "raene-wolfrunner", name = "Raene Wolfrunner", note = "le envió a los buscadores de la vara" },
	},
})

Translate("esES", "krolg", {
	title = "Krolg",
	subtitle = "El fúrbolg incorrupto",
	found = "Una choza solitaria al sur del Lago Mystral",
	hint = "Encuentre al fúrbolg que vive solo al sur del Lago Mystral.",
	allegiance = "Fúrbolgs",
	sections = {
		{
			title = "Resumen",
			text = [=[Krolg es un {link:furbolgs}fúrbolg{/link} que ha escapado del musgo vil y de su corrupción. Fue expulsado de su tribu y vive solo. Solo habla con los de su especie. Krolg culpa a los elfos de la noche de lo que ha caído sobre los fúrbolgs, y su odio arde. Aun así, es justo. No quiere ver sufrir a niños elfos, y sostiene que los fúrbolgs deben responder de su propio mal. Por eso pidió que se diera muerte a {link:ran-bloodtooth}Ran Bloodtooth{/link}.]=],
		},
		{
			title = "Hazañas",
			text = [=[• Se reveló ante alguien que llegó con la forma de un {link:furbolgs}fúrbolg{/link}.
• Pidió la muerte de {link:ran-bloodtooth}Ran Bloodtooth{/link}.]=],
		},
	},
	mentions = {
		{ text = "La purificación de {link:raene-wolfrunner}Raene{/link}" },
		{ text = "La purificación de {link:raene-wolfrunner}Raene{/link}" },
	},
	bonds = {
		{ id = "ran-bloodtooth", name = "Ran Bloodtooth", note = "el mal al que quería poner fin" },
		{ id = "raene-wolfrunner", name = "Raene Wolfrunner", note = "una aliada sin saberlo" },
	},
})

Translate("esES", "ran-bloodtooth", {
	title = "Ran Bloodtooth",
	subtitle = "Rey de los Sangradientes",
	found = "Asentamiento Sangradientes, en el sur de Vallefresno",
	hint = [=[Cuídese del señor fúrbolg cuyo asentamiento se encuentra cerca del límite sur del bosque.]=],
	allegiance = "Fúrbolgs",
	sections = {
		{
			title = "Resumen",
			text = [=[Ran Bloodtooth es el más temido de los fúrbolgs corrompidos de {link:ashenvale}Vallefresno{/link}. Ya ansiaba el poder antes de que la corrupción lo tocara, y la corrupción no ha hecho más que fortalecerlo. Su mente ya no le pertenece. Su odio arde aún más que el de {link:krolg}Krolg{/link}, y es una amenaza para todas las criaturas del bosque. Las {link:sentinels}Centinelas{/link} lo declararon la amenaza {link:furbolgs}fúrbolg{/link} más feroz de Vallefresno. Su cráneo reposa ahora en un lugar de honor en {link:astranaar}Astranaar{/link}.]=],
		},
	},
	mentions = {
		{ text = "La purificación de {link:raene-wolfrunner}Raene{/link}" },
		{ text = "La purificación de {link:raene-wolfrunner}Raene{/link}" },
	},
	bonds = {
		{ id = "krolg", name = "Krolg", note = "lo quería muerto" },
		{ id = "raene-wolfrunner", name = "Raene Wolfrunner", note = "guarda su cráneo" },
	},
})

Translate("esES", "dal-bloodclaw", {
	title = "Dal Bloodclaw",
	subtitle = "Cacique de los Piel de Cardo",
	found = "Poblado Piel de Cardo, al norte de Astranaar",
	hint = "Busque al cacique de los fúrbolgs al norte de Astranaar.",
	allegiance = "Fúrbolgs · Piel de Cardo",
	sections = {
		{
			title = "Resumen",
			text = [=[Dal Bloodclaw es el cacique de los fúrbolgs {link:thistlefur-village}Piel de Cardo{/link}. Bajo su mando la tribu ha crecido mucho en número, y los exploradores de {link:astranaar}Astranaar{/link} temen que pronto se atreva a atacar el pueblo. {link:raene-wolfrunner}Raene Wolfrunner{/link} pidió su cráneo, como prueba de que los Piel de Cardo habían sido contenidos. No fingió que eso pondría fin a la amenaza. Ganaría tiempo, y el tiempo era todo lo que podía esperar.]=],
		},
	},
	mentions = {
