	sections = {
		{
			title = "Resumen",
			text = [=[Pelturas Whitemoon es un {link:night-elves}elfo de la noche{/link} de {link:astranaar}Astranaar{/link} cuya hija, Relara, cayó gravemente enferma. Su mal era algo más que una enfermedad del cuerpo. La atormentaban las pesadillas, ardía de fiebre y se debilitaba de hora en hora. El druida {link:orendil-broadleaf}Orendil Broadleaf{/link} le envió una cura y le habló de otros remedios por si fallaba. Pelturas los siguió todos.]=],
		},
	},
	chapters = {
		{
			title = "La curación de Relara",
			hint = [=[Reúna los remedios de Orendil para la niña enferma de Astranaar.]=],
			text = [=[La primera cura solo frenó la enfermedad. La Lágrima de Elune, del islote del {link:iris-lake}Lago Iris{/link}, lavó las pesadillas. El polvo escarchado de las {link:the-ruins-of-stardust}Ruinas del Polvo Estelar{/link} rompió la fiebre. Por último, una piedra lunar caída, arrancada del tesoro del oráculo Shadethicket, devolvió a Relara sus fuerzas. Pelturas regaló en agradecimiento su posesión más querida.]=],
		},
	},
	mentions = {
		{ text = "La cura de {link:orendil-broadleaf}Orendil{/link}" },
		{ text = "La Lágrima de Elune" },
		{
			text = [=[{link:the-ruins-of-stardust}Las Ruinas del Polvo Estelar{/link}]=],
		},
	},
	bonds = {
		{ id = "orendil-broadleaf", name = "Orendil Broadleaf", note = "envió las curas" },
	},
})

