			text = [=[Kayneth Stillwind custodia el santuario de {link:forest-song}Canción del Bosque{/link}. Teme que una maldad se mueva por {link:ashenvale}Vallefresno{/link}, y lee cada informe de las {link:sentinels}Centinelas{/link} en busca de señales de ella. Encontró una en los {link:forsaken}Renegados{/link}, que se infiltraron en los túmulos de los elfos. Mientras analizaba sus venenos tuvo una visión: los druidas de {link:the-dor-danil-barrow-den}Dor'Danil{/link}, asesinados mientras dormían y alzados como fantasmas enloquecidos. Pidió que se destruyera a sus líderes para que los demás pudieran encontrar la paz. Sintió que la angustia se aliviaba cuando se hizo.]=],
		},
	},
	chapters = {
		{
			title = "Los druidas de Dor'Danil",
			hint = "Averigüe qué preparan los Renegados junto a los túmulos.",
			text = [=[Los {link:forsaken}Renegados{/link} tenían un campamento junto al {link:the-dor-danil-barrow-den}Túmulo de Dor'danil{/link} donde embotellaban venenos y enfermedades. Kayneth creía que pretendían extender la enfermedad por las tierras de los elfos. Tenía razón, y era peor. Los druidas del túmulo habían sido envenenados, y Taneel Darkwood, Uthil Mooncall y Mavoris Cloudsbreak, que antes fueron sus líderes, guiaban ahora una hueste de espíritus enloquecidos. Kayneth llamó a su final una tarea sombría, porque solo eran víctimas.]=],
		},
	},
	mentions = {
		{ text = "Kayneth Stillwind" },
		{ text = "Espíritu antiguo" },
	},
	bonds = {
		{ id = "shindrell-swiftfire", name = "Shindrell Swiftfire", note = "le envía informes" },
	},
})

