		{ text = "La zarpa de {link:ursangous}Ursangous{/link}" },
		{ text = "La cabeza de {link:shadumbra}Shadumbra{/link}" },
		{ text = "La garra de {link:sharptalon}Sharptalon{/link}" },
	},
	bonds = {
		{ id = "ursangous", name = "Ursangous", note = "una de las tres bestias" },
		{ id = "shadumbra", name = "Shadumbra", note = "una de las tres bestias" },
		{ id = "sharptalon", name = "Sharptalon", note = "una de las tres bestias" },
	},
})

