Translate("esES", "je-neu-sancrea", {
	title = "Je'neu Sancrea",
	subtitle = "Chamán del Anillo de la Tierra",
	found = "Avanzada de Zoram'gar, junto al mar",
	hint = [=[Hable con el trol del Anillo de la Tierra que observa las olas en Zoram'gar.]=],
	allegiance = "Anillo de la Tierra · Horda",
	aliases = { "Je'neu" },
	sections = {
		{
			title = "Resumen",
			text = [=[Je'neu Sancrea es un chamán trol del {link:earthen-ring}Anillo de la Tierra{/link} que vive en la {link:zoram-gar-outpost}Avanzada de Zoram'gar{/link}. Estudia el agua y todos los elementos con tanta atención que a menudo no repara en la gente que lo rodea. Llegó a {link:the-zoram-strand}La Ensanada de Zoram{/link} por orden del Anillo de la Tierra, porque algo bajo el mar está volviendo los elementos contra el mundo.]=],
		},
		{
			title = "Importancia",
			text = [=[Je'neu es el vigía de la {link:horde}Horda{/link} sobre las {link:blackfathom-deeps}Cavernas de Brazanegra{/link}. Por él supo el {link:earthen-ring}Anillo de la Tierra{/link} que el {link:twilight-s-hammer}Martillo Crepuscular{/link} había llegado al templo anegado, y que pretendía despertar poderes que los chamanes habían esperado desaparecidos para siempre.]=],
		},
		{
			title = "Hazañas",
			text = [=[• Estudió el orbe corrompido del {link:mystral-lake}Lago Mystral{/link}.
• Averiguó el nombre de {link:lorgus-jett}Lorgus Jett{/link} y pidió su muerte.
• Buscó un núcleo de las profundidades que registra toda la actividad elemental de las ruinas.
• Estudió el orbe que alimentaba al elemental corrompido {link:baron-aquanis}Barón Aquanis{/link}.]=],
		},
	},
	chapters = {
		{
			title = "Los zafiros de Aku'Mai",
			hint = [=[Averigüe por qué los nagas recogen cristales en los túneles de Brazanegra.]=],
			text = [=[En los primeros túneles de las {link:blackfathom-deeps}Cavernas de Brazanegra{/link} crecen en las paredes grandes racimos de zafiros, y los espíritus del agua se aferran a ellos. Los nagas habían empezado a recogerlos. Je'neu no sabía por qué, pero temía que los cristales pudieran convertirse en un arma poderosa en malas manos. Hizo que se los llevaran antes de que los nagas pudieran usarlos.]=],
		},
		{
			title = "Lealtad a los Dioses Antiguos",
			hint = "Siga la nota húmeda hallada en las profundidades.",
			text = [=[Una nota arrugada contaba el resto. Las sacerdotisas de los nagas debían llevar los cristales a un hombre llamado {link:lorgus-jett}Lorgus Jett{/link}, que pretendía usar su poder para complacer a un ser llamado {link:aku-mai}Aku'Mai{/link} y devolverlo al mundo. Soñaba con una nueva era gobernada por los Dioses Antiguos. Lorgus pertenecía al {link:twilight-s-hammer}Martillo Crepuscular{/link}. Je'neu era demasiado débil para enfrentarse a él, y envió a otros a las profundidades para acabar con él.]=],
		},
		{
			title = "El núcleo de las profundidades",
			hint = "Busque la piedra que recuerda a los elementos.",
			text = [=[El {link:twilight-s-hammer}Martillo Crepuscular{/link} había tomado las Moonshrine Ruins, dentro de las cavernas. Je'neu pidió el núcleo de las profundidades que había en la piedra de las profundidades de las ruinas, un artefacto que guarda el registro de cada movimiento de los elementos. Con él, y con el extraño orbe que había alimentado al corrompido {link:baron-aquanis}Barón Aquanis{/link}, el {link:earthen-ring}Anillo de la Tierra{/link} podría empezar a averiguar qué hacía el culto, y cómo.]=],
		},
	},
	mentions = {
		{ text = "Je'neu del {link:earthen-ring}Anillo de la Tierra{/link}" },
		{ text = "Problemas en las profundidades" },
	},
	bonds = {
		{ id = "mastok-wrilehiss", name = "Mastok Wrilehiss", note = "le envió el orbe" },
		{ id = "tideress", name = "Tideress", note = "el espíritu corrompido que estudió" },
		{ id = "karang-amakkar", name = "Karang Amakkar", note = "manda su avanzada" },
	},
})

